    if (file == null) {
        throw new NullPointerException("file");
    }
    ExitHook hook = new ExitHook() {
        public void run() {
            file.delete();
        }
    };
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                if (f.isDirectory()) {
                    forceDeleteOnExit(f);
                }
            }
        }
    }
    Runtime.getRuntime().addShutdownHook(hook);
}

