    // partition and connecting them to all vertices in the second partition.
    List<V> firstPartition = new ArrayList<>(target.getVertexCount() / 2);
    List<V> secondPartition = new ArrayList<>(target.getVertexCount() / 2);
    for (V vertex : target.getVertices()) {
