    // Move all vertices from bucket with minimum label to bucket with label 0
    for (int i = 0; i < numBuckets; i++) {
        if (bucketsByLabel.get(i).size() > 0 && i == minLabel) {
            // Move all vertices from current bucket to bucket with label 0
            for (int vertex : bucketsByLabel.get(i)) {
                bucketsByLabel.get(0).add(vertex);
